import numpy as np

def calculate_stats_for_students(test_results):
    """
    Calculate the average test score and standard deviation for each student.

    Parameters:
    test_results (list of dict): Each dictionary represents one test result and
        contains the student's ID under one of the keys 'student_id', 'id', or
        'Student', and the score under 'score', 'Score', or 'test_score'.

    Returns:
    dict: Keys are student IDs; values are tuples (average_score, std_deviation).

    Raises:
    ValueError: If a student does not have any test scores, or the input is empty/invalid.
    """
    id_keys = ('student_id', 'Student', 'id', 'student')
    score_keys = ('score', 'Score', 'test_score', 'grade')

    grouped = {}

    if test_results is None:
        raise ValueError("test_results must not be None")

    for record in test_results:
        if not isinstance(record, dict):
            raise ValueError("Each test result must be a dictionary")

        student_id = None
        for key in id_keys:
            if key in record:
                student_id = record[key]
                break
        if student_id is None:
            raise ValueError("Test result is missing a student ID")

        score = None
        for key in score_keys:
            if key in record:
                score = record[key]
                break

        if score is None or (isinstance(score, float) and np.isnan(score)):
            # No valid score in this record
            if score is None and not any(k in record for k in score_keys):
                # Student appears but has no score field at all -> no test scores
                grouped.setdefault(student_id, [])
                continue
            grouped.setdefault(student_id, [])
            continue

        grouped.setdefault(student_id, []).append(float(score))

    # Students that appear in the data but had no scores at all
    id_only = set()
    for record in test_results:
        for key in id_keys:
            if key in record:
                id_only.add(record[key])
                break

    results = {}
    for student_id in id_only:
        scores = grouped.get(student_id, [])
        if len(scores) == 0:
            raise ValueError(f"Student {student_id} does not have any test scores")
        avg = float(np.mean(scores))
        std = float(np.std(scores))
        results[student_id] = (avg, std)

    return results


